// audio-streamer.ts
type TransportMode = 'binary' | 'json';

export interface AudioStreamerOptions {
  wsUrl: string;
  inRate?: number;       // sample rate gửi lên server (mặc định 16000)
  outRate?: number;      // sample rate server trả về (mặc định 24000)
  chunkMs?: number;      // kích thước khung ghi (mặc định 40ms)
  transport?: TransportMode; // 'binary' (ưu tiên) | 'json' (base64)
  pingIntervalMs?: number;   // keep-alive
  debug?: boolean;
  token?: string;        // nếu cần token qua query ?token=...
}

export class AudioStreamer {
  private ws?: WebSocket;
  private audioCtx?: AudioContext;
  private recNode?: AudioWorkletNode;
  private playNode?: AudioWorkletNode;
  private source?: MediaStreamAudioSourceNode;
  private media?: MediaStream;

  private cfg!: Required<AudioStreamerOptions>;
  private pingTimer?: number;
  private startedAt?: number;
  private stopped = false;

  // Callbacks
  onText?: (t: string) => void;
  onEvent?: (e: any) => void;
  onStateChange?: (s: 'idle' | 'connecting' | 'streaming' | 'stopped' | 'error') => void;
  onError?: (err: Error) => void;
  onLevel?: (rms: number) => void; // monitor VU

  constructor() {}

  private setState(s: 'idle' | 'connecting' | 'streaming' | 'stopped' | 'error') {
    this.cfg?.debug && console.log('[AudioStreamer] state:', s);
    this.onStateChange?.(s);
  }

  async start(options: AudioStreamerOptions) {
    this.stopped = false;

    // --- 0) Hợp nhất cấu hình
    const defaults: Required<AudioStreamerOptions> = {
      wsUrl: options.wsUrl,
      inRate: options.inRate ?? 16000,
      outRate: options.outRate ?? 24000,
      chunkMs: options.chunkMs ?? 40,
      transport: options.transport ?? 'binary',
      pingIntervalMs: options.pingIntervalMs ?? 15000,
      debug: !!options.debug,
      token: options.token ?? ''
    };
    this.cfg = defaults;

    // --- 1) AudioContext + Worklets
    this.setState('connecting');
    this.audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({
      latencyHint: 'interactive'
    });

    // Một số trình duyệt yêu cầu user gesture và resume sau khi tạo
    if (this.audioCtx.state === 'suspended') {
      try { await this.audioCtx.resume(); } catch {}
    }

    // Nạp worklets (đảm bảo các file được host đúng path/CORS)
    await this.audioCtx.audioWorklet.addModule('/recorder-worklet.js');
    await this.audioCtx.audioWorklet.addModule('/player-worklet.js');

    // --- 2) Mic -> RecorderWorklet
    this.media = await navigator.mediaDevices.getUserMedia({ audio: true });
    this.source = this.audioCtx.createMediaStreamSource(this.media);

    // Truyền cấu hình cho worklet ghi: outRate, chunkSamples
    const chunkSamples = Math.round(this.cfg.inRate * (this.cfg.chunkMs / 1000)); // ví dụ 640 mẫu cho 40ms @16k
    this.recNode = new AudioWorkletNode(this.audioCtx, 'recorder-processor', {
      processorOptions: {
        targetRate: this.cfg.inRate,
        chunkSamples,
        vuMeter: true
      }
    });
    this.source.connect(this.recNode);

    // --- 3) PlayerWorklet -> Destination
    this.playNode = new AudioWorkletNode(this.audioCtx, 'player-processor', {
      numberOfOutputs: 1,
      numberOfInputs: 0
    });
    this.playNode.connect(this.audioCtx.destination);

    // --- 4) WebSocket
    const wsUrl = this.cfg.token
      ? this.cfg.wsUrl + (this.cfg.wsUrl.includes('?') ? '&' : '?') + 'token=' + encodeURIComponent(this.cfg.token)
      : this.cfg.wsUrl;

    this.ws = new WebSocket(wsUrl);
    this.ws.binaryType = 'arraybuffer';

    await new Promise<void>((resolve, reject) => {
      const to = setTimeout(() => reject(new Error('WS open timeout')), 6000);
      this.ws!.onopen = () => { clearTimeout(to); resolve(); };
      this.ws!.onerror = (e: any) => { clearTimeout(to); reject(e instanceof Error ? e : new Error('WS error')); };
    });

    // Khai báo mime IN/OUT (nếu server dùng dạng config như bạn đã có)
    this.ws.send(JSON.stringify({
      type: 'config', direction: 'in', mime_type: `audio/pcm;rate=${this.cfg.inRate}`
    }));
    this.ws.send(JSON.stringify({
      type: 'config', direction: 'out', mime_type: `audio/pcm;rate=${this.cfg.outRate}`
    }));

    // --- 5) Đẩy PCM16 lên server (từ RecorderWorklet)
    this.recNode.port.onmessage = (evt: MessageEvent) => {
      const data = evt.data;
      if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;

      if (data?.type === 'vu') {
        // RMS cho VU meter
        this.onLevel?.(data.rms);
        return;
      }

      if (data instanceof ArrayBuffer) {
        // data là PCM16 @inRate, độ dài chunkSamples * 2 bytes
        if (this.cfg.transport === 'binary') {
          this.ws.send(data);
        } else {
          // JSON base64
          const b64 = this.arrayBufferToBase64(data);
          this.ws.send(JSON.stringify({
            type: 'chunk',
            direction: 'in',
            data: b64,
            mime_type: `audio/pcm;rate=${this.cfg.inRate}`
          }));
        }
      }
    };

    // --- 6) Nhận dữ liệu (PCM16 @outRate) và phát
    this.ws.onmessage = async (event) => {
      try {
        if (typeof event.data === 'string') {
          // JSON: text / event / audio_out_base64
          let msg: any;
          try { msg = JSON.parse(event.data); } catch { msg = null; }
          if (msg) {
            if (msg.type === 'text') this.onText?.(msg.text);
            if (msg.type === 'event') {
              this.onEvent?.(msg);
              if (msg.name === 'interrupted' || msg.type === 'interrupted') {
                // Barge-in: flush queue phát ngay
                this.playNode?.port.postMessage({ type: 'flush' });
              }
            }
            if (msg.type === 'audio_out_base64' && msg.data) {
              const raw = this.base64ToArrayBuffer(msg.data);
              const i16 = new Int16Array(raw);
              const f32 = this.pcm16ToFloat32(i16);
              const f32Out = this.resampleFloat32Cubic(
                f32, this.cfg.outRate, this.audioCtx!.sampleRate
              );
              // Transfer để tránh copy
              const buf = f32Out.buffer;
              this.playNode?.port.postMessage(new Float32Array(buf), [buf]);
            }
            return;
          }
          // Nếu là string nhưng không phải JSON -> bỏ qua
          return;
        }

        if (event.data instanceof ArrayBuffer) {
          // Nhị phân: coi như PCM16 @outRate
          const i16 = new Int16Array(event.data);
          const f32 = this.pcm16ToFloat32(i16);
          const f32Out = this.resampleFloat32Cubic(
            f32, this.cfg.outRate, this.audioCtx!.sampleRate
          );
          const buf = f32Out.buffer;
          this.playNode?.port.postMessage(new Float32Array(buf), [buf]);
        }
      } catch (err: any) {
        this.cfg.debug && console.error('[AudioStreamer] onmessage error', err);
      }
    };

    // Keep-alive ping
    this.pingTimer = window.setInterval(() => {
      try { this.ws?.send(JSON.stringify({ type: 'ping', t: Date.now() })); } catch {}
    }, this.cfg.pingIntervalMs);

    this.startedAt = performance.now();
    this.setState('streaming');
  }

  stop(graceful = true) {
    this.stopped = true;
    this.setState('stopped');

    try { if (graceful) this.ws?.send(JSON.stringify({ type: 'done' })); } catch {}
    try { this.ws?.close(); } catch {}
    try { this.recNode?.disconnect(); } catch {}
    try { this.playNode?.disconnect(); } catch {}
    try { this.source?.disconnect(); } catch {}
    try { this.media?.getTracks().forEach(t => t.stop()); } catch {}
    try { if (this.audioCtx && this.audioCtx.state !== 'closed') this.audioCtx.close(); } catch {}
    if (this.pingTimer) { clearInterval(this.pingTimer); this.pingTimer = undefined; }

    this.ws = undefined;
    this.recNode = undefined;
    this.playNode = undefined;
    this.source = undefined;
    this.media = undefined;
    this.audioCtx = undefined;
  }

  // --- Utils

  private pcm16ToFloat32(i16: Int16Array) {
    const f32 = new Float32Array(i16.length);
    for (let i = 0; i < i16.length; i++) f32[i] = Math.max(-1, i16[i] / 32768);
    return f32;
  }

  // Cubic Hermite interpolation – chất lượng tốt hơn linear, chi phí thấp
  private resampleFloat32Cubic(input: Float32Array, inRate: number, outRate: number) {
    if (inRate === outRate) return input;
    const ratio = inRate / outRate;
    const outLen = Math.floor(input.length / ratio);
    const out = new Float32Array(outLen);

    // Helper: Hermite cubic
    const cubic = (y0: number, y1: number, y2: number, y3: number, t: number) => {
      const a0 = -0.5*y0 + 1.5*y1 - 1.5*y2 + 0.5*y3;
      const a1 = y0 - 2.5*y1 + 2*y2 - 0.5*y3;
      const a2 = -0.5*y0 + 0.5*y2;
      const a3 = y1;
      return ((a0*t + a1)*t + a2)*t + a3;
    };

    for (let i = 0; i < outLen; i++) {
      const idx = i * ratio;
      const i1 = Math.floor(idx);
      const t = idx - i1;

      const i0 = Math.max(0, i1 - 1);
      const i2 = Math.min(input.length - 1, i1 + 1);
      const i3 = Math.min(input.length - 1, i1 + 2);

      out[i] = cubic(input[i0], input[i1], input[i2], input[i3], t);
    }
    return out;
  }

  private arrayBufferToBase64(buf: ArrayBuffer) {
    const bin = String.fromCharCode(...new Uint8Array(buf));
    return btoa(bin);
  }
  private base64ToArrayBuffer(b64: string) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }
}